1	public class DS01_1 {
2	    public static void main(String[] args) {
3	        String[] samples = {"PAB", "5C", "PABC", "CXY", "CRSI", "7", "B899", "B9"}; //待排序数据集
4	        quickSort(samples, 0, samples.length - 1);
5	        for (int i = 0; i < samples.length; i ++) {
6	            System.out.print(samples[i] + " ");
7	        }
8	    }
9	    //快速排序方法
10	    private static void quickSort(String[] samples, int start, int end) {
11	        if(start >= end) {
12	            return;
13	        }
14	        String pivot = samples[start]; //以区间的第一个元素作为基准
15	        int left = start;
16	        int right = end;
17	        while(left < right) {
18	            //从右向左找第一个小于基准的元素
19	            while(left < right && myCompare(samples[right], pivot) >= 0) {
20	                right --;
21	            }
22	            samples[left] = samples[right];
23	            //从左向右找第一个大于基准的元素
24	            while(left < right && myCompare(samples[left], pivot) <= 0) {
25	                left ++;
26	            }
27	            samples[right] = samples[left];
28	        }
29	        samples[left] = pivot; //基准归位
30	        quickSort(samples, start, left - 1);
31	        quickSort(samples, left + 1, end);
32	    }
33	    //按照给定顺序比较两个字符串的方法
34	    private static int myCompare(String a, String b) {
35	        int length = a.length() < b.length() ? a.length() : b.length();
36	        //逐个字符比较，遇到不同的字符即可确定顺序
37	        for(int i = 0; i < length; i ++) {
38	            if(a.charAt(i) != b.charAt(i)) {
39	                return a.charAt(i) - b.charAt(i);
40	            }
41	        }
42	        //一个字符串是另一个的前缀时，较短的排在前面
43	        return a.length() - b.length();
44	    }
45	}

