4	public class DS01_2 {
5	    private static int maxNumber;
6	    private static ArrayList<Integer> maxIndex = new ArrayList<>();
7	    public static void main(String[] args) {
8	        int[] samples = new int[100];
9	        Random random = new Random();
10	        for(int i = 0; i < 100; i ++) {  
11	            samples[i] = random.nextInt(999) + 1;
12	            System.out.print(samples[i] + " ");
13	        }
14	        System.out.println();
15	        findMax(samples);
16	        System.out.println("The max number is " + maxNumber + " and the max index is " + maxIndex.toString());
17	    }
18	    //从两侧向中间查找最大值的方法
19	    private static void findMax(int[] samples) {
20	        maxIndex.clear();
21	        maxNumber = samples[0];
22	        int leftCount = 0; //已经从左侧记录的下标个数，用于保证下标升序排列
23	        int i = 0;
24	        int j = samples.length - 1;
25	        while(i <= j) {
26	            //处理左侧指针指向的元素
27	            if(samples[i] > maxNumber) {
28	                maxNumber = samples[i];
29	                maxIndex.clear();
30	                leftCount = 0;
31	            }
32	            if(samples[i] == maxNumber) {
33	                maxIndex.add(leftCount, i);
34	                leftCount ++;
35	            }
36	            //处理右侧指针指向的元素，两指针相遇时中间的元素只记录一次
37	            if(i != j) {
38	                if(samples[j] > maxNumber) {
39	                    maxNumber = samples[j];
40	                    maxIndex.clear();
41	                    leftCount = 0;
42	                }
43	                if(samples[j] == maxNumber) {
44	                    maxIndex.add(leftCount, j);
45	                }
46	            }
47	            i ++;
48	            j --;
49	        }
50	    }
51	}

