53	    private static void findAWay() {
54	        stack = new Stack();
55	        //随机选择一支队伍作为起点
56	        stack.push(nodeList.get((int)(Math.random() * teamNumber)));
57	        stack.getTop().setTrue();
58	        while(!stack.isFull()) {
59	            //栈已空，重新寻找一个未访问过的队伍作为起点
60	            if(stack.isEmpty()) {
61	                for(int i = 0; i < teamNumber; i ++) {
62	                    if(!nodeList.get(i).getHasGet()) {
63	                        stack.push(nodeList.get(i));
64	                        stack.getTop().setTrue();
65	                        break;
66	                    }
67	                }
68	            }
69	            //所有队伍都已访问过但仍未凑出通路
70	            if(stack.isEmpty()) {
71	                System.out.println("\n该组数据无哈密顿通路！");
72	                System.exit(0);
73	            }
74	            //收集栈顶队伍可以到达且未被访问过的队伍
75	            int[] temp = graph[stack.getTop().getIndex()];
76	            ArrayList<Node> nextList = new ArrayList<>();
77	            for(int i = 0; i < teamNumber; i ++) {
78	                if(temp[i] == 1 && !nodeList.get(i).getHasGet()) {
79	                    nextList.add(nodeList.get(i));
80	                }
81	            }
82	            //无路可走则回退，否则随机选择一支队伍继续深入
83	            if(nextList.isEmpty()) {
84	                stack.pop();
85	                continue;
86	            }
87	            stack.push(nextList.get((int)(Math.random() * nextList.size())));
88	            stack.getTop().setTrue();
89	        }
90	    }
