        for (int t = 0; t < 20000; t++) {
            int n = 1 + r.nextInt(12);
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = r.nextInt(4);
            if (!verify(arr, false)) { bad++; if (bad <= 5) verify(arr, true); }
        }
        System.out.println("\nFUZZ 20000 arrays (len 1-12, values 0-3): mismatches = " + bad);
    }

    static void check(int[] arr) throws Exception {
        boolean ok = verify(arr, true);
        System.out.println("   -> " + (ok ? "PASS" : "*** FAIL ***"));
    }

    @SuppressWarnings("unchecked")
    static boolean verify(int[] arr, boolean print) throws Exception {
        findMax.invoke(null, (Object) arr.clone());
        int gotMax = (Integer) fMaxNumber.get(null);
        List<Integer> gotIdx = new ArrayList<>((List<Integer>) fMaxIndex.get(null));

        int expMax = arr[0];
        for (int v : arr) if (v > expMax) expMax = v;
        List<Integer> expIdx = new ArrayList<>();
        for (int i = 0; i < arr.length; i++) if (arr[i] == expMax) expIdx.add(i);

        boolean ok = gotMax == expMax && gotIdx.equals(expIdx);
        if (print) {
            System.out.println(Arrays.toString(arr));
            System.out.println("   got  max=" + gotMax + " idx=" + gotIdx);
            System.out.println("   want max=" + expMax + " idx=" + expIdx);
        }
        return ok;
    }
}

import java.lang.reflect.*;
import java.util.*;

public class SortTest {
    static Method quickSort, myCompare;

    public static void main(String[] a) throws Exception {
        Class<?> c = Class.forName("DS01_1");
        quickSort = c.getDeclaredMethod("quickSort", String[].class, int.class, int.class);
        quickSort.setAccessible(true);
        myCompare = c.getDeclaredMethod("myCompare", String.class, String.class);
        myCompare.setAccessible(true);

        // comparator contract spot checks
        cmp("PAB", "PABC");   // prefix -> shorter first
        cmp("PABC", "PAB");
        cmp("B899", "B9");    // first difference decides
        cmp("5C", "7");
        cmp("CXY", "CRSI");
        cmp("ABC", "ABC");    // equal -> 0

        String[] course = {"PAB", "5C", "PABC", "CXY", "CRSI", "7", "B899", "B9"};
        run(course);

        run(new String[]{});
        run(new String[]{"only"});
        run(new String[]{"b","a"});
        run(new String[]{"a","a","a","a","a"});                 // all duplicates
        run(new String[]{"","a","","ab","a"});                  // empty strings + prefixes
        run(new String[]{"e","d","c","b","a"});                 // reverse sorted
        run(new String[]{"a","b","c","d","e"});                 // already sorted
        run(new String[]{"A","a","z","Z","0","9"});             // case + digits (ASCII order)
        run(new String[]{"P","PA","PAB","PABC","PABCD"});       // prefix chain

        Random r = new Random(999);
        int bad = 0;
        String alpha = "ab5C";
        for (int t = 0; t < 20000; t++) {
            int n = r.nextInt(10);
            String[] arr = new String[n];
            for (int i = 0; i < n; i++) {
                int len = r.nextInt(4);
                StringBuilder sb = new StringBuilder();
                for (int k = 0; k < len; k++) sb.append(alpha.charAt(r.nextInt(alpha.length())));
                arr[i] = sb.toString();
            }
            if (!verify(arr, false)) { bad++; if (bad <= 5) verify(arr, true); }
        }
        System.out.println("\nFUZZ 20000 arrays (len 0-9, heavy duplicates/prefixes): mismatches = " + bad);
    }

    static void cmp(String x, String y) throws Exception {
        int got = (Integer) myCompare.invoke(null, x, y);
        int want = x.compareTo(y);
        System.out.println("myCompare(\"" + x + "\",\"" + y + "\") = " + got
                + "   sign=" + Integer.signum(got) + "   String.compareTo sign=" + Integer.signum(want)
                + (Integer.signum(got) == Integer.signum(want) ? "  PASS" : "  *** FAIL ***"));
    }

    static void run(String[] arr) throws Exception {
        String[] in = arr.clone();
        boolean ok = verify(arr, true);
        System.out.println("   in : " + Arrays.toString(in));
        System.out.println("   -> " + (ok ? "PASS" : "*** FAIL ***"));
    }

    static boolean verify(String[] arr, boolean print) throws Exception {
        String[] work = arr.clone();
        quickSort.invoke(null, work, 0, work.length - 1);
        String[] want = arr.clone();
        Arrays.sort(want);
        boolean sorted = true;
        for (int i = 1; i < work.length; i++)
            if ((Integer) myCompare.invoke(null, work[i - 1], work[i]) > 0) sorted = false;
        // multiset preservation
        List<String> l1 = new ArrayList<>(Arrays.asList(arr)), l2 = new ArrayList<>(Arrays.asList(work));
        Collections.sort(l1); Collections.sort(l2);
        boolean sameMultiset = l1.equals(l2);
        boolean ok = sorted && sameMultiset && Arrays.equals(work, want);
        if (print) System.out.println("   out: " + Arrays.toString(work)
                + "  sortedByMyCompare=" + sorted + " multisetPreserved=" + sameMultiset
                + " matchesArrays.sort=" + Arrays.equals(work, want));
        return ok;
    }
}

import sys, re
team = int(sys.argv[1])
text = sys.stdin.read()
lines = [l.rstrip() for l in text.splitlines()]
# adjacency matrix rows: lines made only of 0/1 and spaces, right after the matrix header
mat = []
for l in lines:
    s = l.strip()
    if s and re.fullmatch(r'[01](\s+[01])*', s):
        row = [int(x) for x in s.split()]
        if len(row) == team:
            mat.append(row)
mat = mat[:team]
m = re.search(r'\[ (.+) \]', text)
if not m or len(mat) != team:
    print("PARSE FAIL", file=sys.stderr); sys.exit(1)
path = [int(x) for x in m.group(1).split(' --> ')]
errs = []
if len(path) != team:
    errs.append(f"path length {len(path)} != teamNumber {team}")
if len(set(path)) != len(path):
    errs.append(f"path revisits a node: {path}")
if sorted(path) != list(range(team)):
    errs.append(f"path is not a permutation of 0..{team-1}: {path}")
for a, b in zip(path, path[1:]):
    if not (0 <= a < team and 0 <= b < team) or mat[a][b] != 1:
        errs.append(f"edge {a}->{b} absent from matrix")
if errs:
    for e in errs: print("ERR:", e, file=sys.stderr)
    sys.exit(1)
sys.exit(0)
